// Run from a checkout: node probe06.mjs <outJson> [query]
import { writeFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
const { loadPlaywright, CHROMIUM_ARGS, startVite } = await import(pathToFileURL(`${process.cwd()}/scripts/lib/pw.mjs`).href);
const [OUT, Q = 'match06=1&m06geo=1&m06flow=1'] = process.argv.slice(2);
const { chromium } = loadPlaywright();
const vite = await startVite(5291);
const browser = await chromium.launch({ args: CHROMIUM_ARGS });
try {
  const page = await browser.newPage({ viewport: { width: 432, height: 768 }, deviceScaleFactor: 1 });
  await page.goto(`${vite.url}/?qa=1&dpr=1&${Q}`);
  await page.waitForFunction(() => window.__rainbow?.ready === true || window.__error, null, { timeout: 300000 });
  const res = await page.evaluate(async () => {
    const r = window.__rainbow; const c = r.course;
    const st = c.stage('06'); const st7 = c.stage('07');
    const prof = [];
    for (let s = st.s0 - 4; s <= st7.s0 + 30; s += 2) {
      const f = c.sample(s);
      prof.push({ s: +s.toFixed(1), y: +f.pos.y.toFixed(2), x: +f.pos.x.toFixed(2), z: +f.pos.z.toFixed(2), slopeDeg: +(Math.asin(f.tan.y) * 180 / Math.PI).toFixed(1), headDeg: +(Math.atan2(f.tan.x, -f.tan.z) * 180 / Math.PI).toFixed(1) });
    }
    r.goto('06');
    const s0 = r.state().s; const shots = [];
    const { camera } = r.qa3d();
    for (const d of [0, 3, 6, 10, 15, 20, 30, 40, 50, 60]) {
      let n = 0; while (r.state().s < s0 + d - 1e-3 && n < 4000) { r.step(1); n++; }
      r.run(true); await new Promise((res) => requestAnimationFrame(() => requestAnimationFrame(res))); r.run(false);
      camera.updateMatrixWorld();
      const s = r.state().s; const proj = (p) => { const v = p.clone().project(camera); return [+(((v.x + 1) / 2)).toFixed(3), +(((1 - v.y) / 2)).toFixed(3), +v.z.toFixed(3)]; };
      const ahead = {};
      for (const k of [10, 20, 40, 80]) { const f = c.sample(Math.min(s + k, c.length - 1)); ahead[k] = proj(f.pos.clone().addScaledVector(f.up, 3)); }
      const fw = camera.getWorldDirection(camera.position.clone().set(0,0,0));
      shots.push({ d, s: +s.toFixed(2), stage: r.state().stage, benny: r.bennyScreen(), camPitchDeg: +(Math.asin(fw.y) * 180 / Math.PI).toFixed(1), tubeCentreAhead: ahead });
    }
    return { st, st7, prof, shots };
  });
  writeFileSync(OUT, JSON.stringify(res, null, 1));
  console.log('stage06', res.st.s0, res.st.s1, 'stage07', res.st7.s0);
  for (const p of res.prof) console.log('s', p.s, 'y', p.y, 'slope', p.slopeDeg, 'head', p.headDeg);
  for (const sh of res.shots) console.log('d', sh.d, 's', sh.s, sh.stage, 'pitch', sh.camPitchDeg, 'benny', sh.benny.x, sh.benny.y, 'ahead10', sh.tubeCentreAhead[10], 'ahead40', sh.tubeCentreAhead[40], 'ahead80', sh.tubeCentreAhead[80]);
} finally { await browser.close(); await vite.close?.(); }

