+  // no more magnified than the approved view did (incidence-cosine ratio x distance ratio = 1 in the approved view)
+  float mag = (cc / max(cp, 1e-3)) * (distance(uProjPos, vW) / max(distance(cameraPosition, vW), 1e-3));
