  const Wr = Number(qs?.get('m06ringw')) || 1.3, Dr = Number(qs?.get('m06ringd')) || 0.55;
  const yPx = (a: number) => {
    const p = O.clone().addScaledVector(ax, a).addScaledVector(Ux, radAt(a)).project(proj);
    return ((1 - p.y) / 2) * H;
  };
  const solve = (rPx: number) => { // painted ring top at vp.y - rPx -> axial position (yPx increases toward the camera)
    let lo = Math.max(a0, C.clone().sub(O).dot(ax) + 1), hi = a1 - 10;
