  rg.computeVertexNormals();
  const rm = mat(tTube);
  Object.assign(rm.uniforms, { uRing: { value: 1 }, uUseMask: { value: 0 }, uAxO: { value: O.clone() }, uAxD: { value: ax.clone() },
